alter table public.tasks_reminders drop constraint if exists tasks_reminders_task_type_check;
alter table public.tasks_reminders add constraint tasks_reminders_task_type_check check(task_type in('follow_up','appointment','customer_call','supplier_check','payment','documents','ticketing','visa','corporate_approval','payment_reminder','document_request','supplier_payment','internal','other'));
create or replace function public.create_booking_task(p_booking_id uuid,p_title text,p_task_type text default 'follow_up',p_due_at timestamptz default null,p_priority text default 'normal',p_notes text default null) returns uuid language plpgsql security definer set search_path='public' as $function$
declare v_id uuid;v_type text:=coalesce(nullif(trim(coalesce(p_task_type,'')),''),'follow_up');begin
 if auth.uid() is null then raise exception 'Authentication required';end if;if not(public.has_staff_permission('edit_bookings') or public.has_staff_permission('create_bookings')) then raise exception 'Booking task permission required';end if;
 if nullif(trim(coalesce(p_title,'')),'') is null then raise exception 'Task title is required';end if;if not exists(select 1 from public.bookings where id=p_booking_id and archived_at is null) then raise exception 'Booking not found';end if;
 if v_type='appointment' and p_due_at is null then raise exception 'Appointment date and time are required';end if;
 insert into public.tasks_reminders(title,task_type,entity_type,entity_id,assigned_to,due_at,status,priority,notes,created_by) values(trim(p_title),v_type,'booking',p_booking_id,auth.uid(),p_due_at,'open',coalesce(nullif(trim(coalesce(p_priority,'')),''),'normal'),nullif(trim(coalesce(p_notes,'')),''),auth.uid()) returning id into v_id;
 if p_due_at is not null then update public.bookings set follow_up_at=p_due_at,updated_at=now() where id=p_booking_id;end if;
 insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata) values(auth.uid(),case when v_type='appointment' then 'booking.appointment_scheduled' else 'booking.task_created' end,'booking',p_booking_id,jsonb_build_object('task_id',v_id,'title',trim(p_title),'task_type',v_type,'due_at',p_due_at,'priority',p_priority));return v_id;end;$function$;
revoke execute on function public.create_booking_task(uuid,text,text,timestamptz,text,text) from public,anon;grant execute on function public.create_booking_task(uuid,text,text,timestamptz,text,text) to authenticated,service_role;
